const b = $json.body || {};
function slugify(s) { return String(s || '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, ''); }
function cleanDomain(v) { return String(v || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, ''); }
const emailDomain = String(b.email || '').split('@')[1] || '';
const domain = cleanDomain(b.site) || emailDomain;
const out = {
  name: b.name, email: b.email, teamEmails: b.teamEmails || '', company: b.company,
  site: b.site || '', social: b.social || '', industry: b.industry || '', painPoint: b.painPoint || '',
  audioSeconds: b.audioSeconds || 0, hasAudio: !!b.audioBase64,
  slug: slugify(b.company), domain,
  logo_url: domain ? ('https://www.google.com/s2/favicons?domain=' + domain + '&sz=128') : null
};
if (b.audioBase64) {
  const mime = b.audioMime || 'audio/webm';
  const ext = mime.includes('wav') ? 'wav' : mime.includes('mp4') ? 'm4a' : mime.includes('ogg') ? 'ogg' : 'webm';
  const bin = await this.helpers.prepareBinaryData(Buffer.from(b.audioBase64, 'base64'), 'pain-point-voice-note.' + ext, mime);
  return { json: out, binary: { voiceNote: bin } };
}
return { json: out };

const prep = $('Prepare Submission').item.json;
const created = $json || {};
const out = Object.assign({}, prep, { client_id: created.id || null, slug: created.slug || prep.slug });
const bin = $('Prepare Submission').item.binary;
if (bin && bin.voiceNote) return { json: out, binary: { voiceNote: bin.voiceNote } };
return { json: out };

