// Re-attach the audio and fold in transcript + summary (both optional —
// if transcription or summarization failed, the email still goes out with the attachment).
const base = $('Merge Client').item.json;
let transcript = '';
let summary = '';
try { transcript = String($('Transcribe Voice Note').item.json.text || '').trim(); } catch (e) {}
try { summary = String($('Summarize Voice Note').item.json.choices[0].message.content || '').trim(); } catch (e) {}
const out = Object.assign({}, base, {
  transcript,
  summary: summary || '- (summary unavailable — see transcript/audio below)'
});
const bin = $('Prepare Submission').item.binary;
if (bin && bin.voiceNote) return { json: out, binary: { voiceNote: bin.voiceNote } };
return { json: out };

